async function fetchUserData() {
  // await 會等待 Promise 完成
  const response = await fetch('/api/user');
  const data = await response.json();

  console.log(data);  // 資料已經拿到了！
  return data;
}

// 呼叫 async 函式
fetchUserData();

// 特點：
