// 3. 更容易閱讀和維護`,highlightLines:[2,4,5,7]}]},{id:"promise-basics",title:"Promise 基礎",description:"Async 函式必須搭配 Promise 才能運作。Promise 代表一個「未來會完成」的操作，有三種狀態：Pending（等待中）、Fulfilled（成功）、Rejected（失敗）。",preview:{type:"component",component:V3},codeBlocks:[{language:"javascript",filename:"promise-example.js",code:`// 建立 Promise
const promise = new Promise((resolve, reject) => {
  // 模擬非同步操作
  setTimeout(() => {
    const success = true;

    if (success) {
      resolve('操作成功！');  // 成功時調用
    } else {
      reject('操作失敗');     // 失敗時調用
    }
  }, 1000);
});

// 使用 Promise
promise
  .then(result => console.log(result))  // 成功
